#if canImport(AVFoundation)
import XCTest
@preconcurrency import AVFoundation
@testable import KriaMediaEngine

/// KRI-1613: an intro scene's sound, exported by the native exporter, starts on its title line's entrance frame.
/// The clips are the server's compiled `sfx` track and the entrances are its title lines' text-layer starts, both
/// from the real Talking worker (`tests/fixtures/intro-scene-sound/`, generated by
/// `src/apps/api/tests/tasks/test_intro_scene_sound_phone_fixture.py`). The expected frames come from the entrances and
/// the cue, never from the clips, so a clip off its entrance fails here.
///
/// Failure modes: a sound a frame or more off its entrance; the accent-only cue also sounding on the first line; a
/// sound missing; any sound with the switch off.
///
/// Set `KRIA_INTRO_SOUND_EVIDENCE_DIR` to keep each exported MP4 and its recipe, then measure them independently with
/// `scripts/verify-colour-moments.py measure <mp4>`.
final class IntroSceneSoundExportTests: XCTestCase {
    private struct Clip: Decodable {
        let id: String
        let timelineStart: Double
        let sourceDuration: Double
        let volume: Double
    }

    private struct Fixture: Decodable {
        let cue: String
        let fps: Double
        let entrancesS: [Double]
        let accentEntranceS: Double
        let sfx: [Clip]
    }

    private static let repo: URL = {
        let path = #filePath
        let root = path.range(of: "/src/apps/ios/")!
        return URL(fileURLWithPath: String(path[..<root.lowerBound]))
    }()
    private let exportSeconds = 2.0
    private let hitSeconds = 0.25
    private let onsetDB = -40.0

    private func fixture(_ name: String) throws -> Fixture {
        let url = Self.repo.appendingPathComponent("tests/fixtures/intro-scene-sound/\(name).json")
        return try RecipeJSON.decoder().decode(Fixture.self, from: Data(contentsOf: url))
    }

    /// A short burst with a fast attack standing in for a library pop, silent after `hitSeconds`.
    private func writeHit(_ directory: URL) throws -> URL {
        let url = directory.appendingPathComponent("hit.m4a")
        let format = try XCTUnwrap(AVAudioFormat(standardFormatWithSampleRate: 48_000, channels: 1))
        let frames = AVAudioFrameCount(0.5 * 48_000)
        let buffer = try XCTUnwrap(AVAudioPCMBuffer(pcmFormat: format, frameCapacity: frames)); buffer.frameLength = frames
        for index in 0..<Int(frames) {
            let t = Double(index) / 48_000
            let envelope = t < hitSeconds ? exp(-t * 12) : 0
            buffer.floatChannelData![0][index] = Float(0.7 * envelope * sin(t * 2 * .pi * 900))
        }
        let file = try AVAudioFile(forWriting: url, settings: [AVFormatIDKey: kAudioFormatMPEG4AAC, AVSampleRateKey: 48_000,
            AVNumberOfChannelsKey: 1, AVEncoderBitRateKey: 128_000], commonFormat: .pcmFormatFloat32, interleaved: false)
        try file.write(from: buffer)
        return url
    }

    private func recipe(_ fixture: Fixture) -> EditRecipe {
        var tracks = [TimelineTrack(id: "subtitled", kind: .video, clips: [
            TimelineClip(id: "clip-0", sourceAssetID: "wall", sourceDuration: exportSeconds, volume: 0)
        ])]
        if !fixture.sfx.isEmpty {
            tracks.append(TimelineTrack(id: "sfx", kind: .audio, clips: fixture.sfx.map {
                TimelineClip(id: $0.id, sourceAssetID: "hit", sourceDuration: min($0.sourceDuration, 0.5),
                             timelineStart: $0.timelineStart, volume: $0.volume)
            }))
        }
        return EditRecipe(canvas: Canvas(width: 96, height: 160), frameRate: fixture.fps,
            assets: [MediaAsset(id: "wall", relativePath: "wall")] + (fixture.sfx.isEmpty ? [] : [MediaAsset(id: "hit", relativePath: "hit")]),
            tracks: tracks)
    }

    /// Per-video-frame RMS level (dBFS) of the exported audio, mixed to mono; an export with no audio track is silent.
    @MainActor private func levels(_ url: URL, fps: Double) async throws -> [Double] {
        let frames = Int(exportSeconds * fps)
        let asset = AVURLAsset(url: url)
        guard let audio = try await asset.loadTracks(withMediaType: .audio).first else { return Array(repeating: -120, count: frames) }
        let reader = try AVAssetReader(asset: asset)
        let output = AVAssetReaderTrackOutput(track: audio, outputSettings: [AVFormatIDKey: kAudioFormatLinearPCM, AVLinearPCMBitDepthKey: 32,
            AVLinearPCMIsFloatKey: true, AVLinearPCMIsNonInterleaved: false, AVSampleRateKey: 48_000, AVNumberOfChannelsKey: 1])
        reader.add(output)
        XCTAssertTrue(reader.startReading())
        var samples: [Float] = []
        while let sample = output.copyNextSampleBuffer(), let block = CMSampleBufferGetDataBuffer(sample) {
            let length = CMBlockBufferGetDataLength(block)
            var chunk = [Float](repeating: 0, count: length / 4)
            _ = chunk.withUnsafeMutableBytes { CMBlockBufferCopyDataBytes(block, atOffset: 0, dataLength: length, destination: $0.baseAddress!) }
            samples += chunk
        }
        let hop = Int(48_000 / fps)
        return (0..<frames).map { frame in
            let slice = samples.dropFirst(frame * hop).prefix(hop)
            guard !slice.isEmpty else { return -120 }
            let power = slice.reduce(0.0) { $0 + Double($1 * $1) } / Double(slice.count)
            return 10 * log10(power + 1e-12)
        }
    }

    @MainActor private func export(_ name: String) async throws -> (Fixture, [Double]) {
        let fixture = try fixture(name)
        let directory = FileManager.default.temporaryDirectory.appendingPathComponent(UUID().uuidString)
        try FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true)
        defer { try? FileManager.default.removeItem(at: directory) }
        let wall = try await SolidVideoFixture.make(directory: directory, name: "wall", color: CGColor(red: 0.2, green: 0.2, blue: 0.25, alpha: 1),
                                                    seconds: exportSeconds + 0.2, fps: Int32(fixture.fps))
        let edit = recipe(fixture)
        try edit.validate()
        let output = directory.appendingPathComponent("\(name).mp4")
        let checkpoint = try await AVFoundationLocalExporter(stateStore: FileExportStateStore(directory: directory.appendingPathComponent("state")), branding: .none)
            .export(recipe: edit, assetURLs: ["wall": wall, "hit": try writeHit(directory)], outputURL: output)
        XCTAssertEqual(checkpoint.status, .completed)
        if let keep = ProcessInfo.processInfo.environment["KRIA_INTRO_SOUND_EVIDENCE_DIR"] {
            let dir = URL(fileURLWithPath: keep)
            try? FileManager.default.createDirectory(at: dir, withIntermediateDirectories: true)
            try? FileManager.default.removeItem(at: dir.appendingPathComponent("\(name).mp4"))
            try FileManager.default.copyItem(at: output, to: dir.appendingPathComponent("\(name).mp4"))
            try RecipeJSON.encode(edit).write(to: dir.appendingPathComponent("\(name).recipe.json"))
        }
        return (fixture, try await levels(output, fps: fixture.fps))
    }

    /// Frames where the level first rises above `onsetDB` (the burst dies out well before the next entrance).
    private func onsets(_ levels: [Double]) -> [Int] {
        levels.indices.filter { levels[$0] > onsetDB && ($0 == 0 || levels[$0 - 1] <= onsetDB) }
    }

    private func entranceFrames(_ fixture: Fixture) -> [Int] {
        switch fixture.cue {
        case "accent": return [Int((fixture.accentEntranceS * fixture.fps).rounded())]
        case "each": return Array(Set(fixture.entrancesS.map { Int(($0 * fixture.fps).rounded()) })).sorted()
        default: return []
        }
    }

    @MainActor func testTheAccentOnlySoundStartsOnTheLateAccentsEntranceFrame() async throws {
        let (fixture, levels) = try await export("accent_en")
        XCTAssertEqual(entranceFrames(fixture), [18], "the accent enters 0.6 s in at 30 fps")
        let found = onsets(levels)
        XCTAssertEqual(found.count, 1, "one sound, none on the first line: \(found)")
        XCTAssertEqual(Double(found.first ?? -99), 18, accuracy: 1, "sound onset vs the accent's entrance frame")
        XCTAssertLessThan(levels[0...10].max()!, -60, "silent while only the first line shows")
    }

    @MainActor func testOnePerEntranceSoundsTheTitleAndThenTheAccent() async throws {
        let (fixture, levels) = try await export("each_tr")
        let expected = entranceFrames(fixture)
        XCTAssertEqual(expected, [0, 18])
        let found = onsets(levels)
        XCTAssertEqual(found.count, expected.count, "one sound per entrance: \(found)")
        for (onset, frame) in zip(found, expected) {
            XCTAssertEqual(Double(onset), Double(frame), accuracy: 1, "sound onset vs entrance frame \(frame)")
        }
    }

    @MainActor func testTheSwitchOffExportIsSilent() async throws {
        let (fixture, levels) = try await export("switch_off_en")
        XCTAssertTrue(fixture.sfx.isEmpty)
        XCTAssertEqual(onsets(levels), [])
        XCTAssertLessThan(levels.max()!, -60, "no sound anywhere in the opening")
    }
}
#endif
